func sftPut(b []byte, c *port.Cells) int32 {
	// Decode the UTF-8 of the blob into code points (cleared first). Answers how many.
	var n int32 = port.BlobLen(b)
	var k int32 = 0
	var x int32 = 0
	port.CellsDrop(c, 0)
	for k < n {
		x = port.BlobU8(b, k)
		if x < 128 {
			port.CellsPush(c, x)
			k += 1
		} else if x < 224 {
			port.CellsPush(c, ((x%32)*64)+(port.BlobU8(b, k+1)%64))
			k += 2
		} else if x < 240 {
			port.CellsPush(c, ((((x%16)*64)+(port.BlobU8(b, k+1)%64))*64)+(port.BlobU8(b, k+2)%64))
			k += 3
		} else {
			port.CellsPush(c, ((((((x%8)*64)+(port.BlobU8(b, k+1)%64))*64)+(port.BlobU8(b, k+2)%64))*64)+(port.BlobU8(b, k+3)%64))
			k += 4
		}
	}
	return port.CellsLen(c)
}

func TestACharacterHasAValueOrAScript(emonT *testing.T) {
	port.AssertEq(emonT, sealfield.SfDigit(55), 7, "an ASCII 7")
	port.AssertEq(emonT, sealfield.SfDigit(1635), 3, "an Arabic-Indic 3")
	port.AssertEq(emonT, sealfield.SfDigit(1782), 6, "an Extended Arabic-Indic 6")
	port.AssertEq(emonT, sealfield.SfDigit(2407), 1, "a Devanagari 1")
	port.AssertEq(emonT, sealfield.SfDigit(65301), 5, "a fullwidth 5")
	port.AssertEq(emonT, sealfield.SfDigit(65), -1, "a letter is none")
	port.AssertEq(emonT, sealfield.SfScript(65), 1, "A is Latin")
	port.AssertEq(emonT, sealfield.SfScript(233), 1, "so is e acute")
	port.AssertEq(emonT, sealfield.SfScript(1040), 3, "Cyrillic A")
	port.AssertEq(emonT, sealfield.SfScript(945), 2, "Greek alpha")
	port.AssertEq(emonT, sealfield.SfScript(20013), 10, "a Han letter")
	port.AssertEq(emonT, sealfield.SfScript(12402), 8, "a Kana")
	port.AssertEq(emonT, sealfield.SfScript(54620), 9, "a Hangul syllable")
	port.AssertEq(emonT, sealfield.SfScript(1575), 5, "an Arabic letter")
	port.AssertEq(emonT, sealfield.SfScript(48), 0, "a digit is no letter")
	port.AssertEq(emonT, sealfield.SfScript(45), 0, "nor a dash")
	port.AssertEq(emonT, sealfield.SfScript(8226), 0, "nor a bullet")
	port.AssertEq(emonT, sealfield.SfScript(215), 0, "nor a multiplication sign")
}

func sftRun(b []byte, et *port.Cells, out *port.Cells, kind int32, order int32) int32 {
	// Decode the text and read its fields into `out`; answers the length of the text.
	var n int32 = sftPut(b, et)
	sealfield.SfFields(et, 0, n, kind, order, out, 0)
	return n
}

func TestADateOfDigitsIsFoundAndWrittenOut(emonT *testing.T) {
	var et *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	sftRun(port.TextBlob("PAID 2026-03-14"), et, out, 2, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 1, "year first, one separator: a date nothing disputes")
	port.AssertEq(emonT, port.CellsAt(out, 3), 5, "it starts after PAID")
	port.AssertEq(emonT, port.CellsAt(out, 4), 10, "and is ten characters")
	port.AssertEq(emonT, port.CellsAt(out, 5), 2026, "the year")
	port.AssertEq(emonT, port.CellsAt(out, 6), 3, "the month")
	port.AssertEq(emonT, port.CellsAt(out, 7), 14, "the day")
	sftRun(port.TextBlob("Date: 2026/4/2."), et, out, 2, 0)
	port.AssertEq(emonT, port.CellsAt(out, 6), 4, "a slash and one-digit parts")
	port.AssertEq(emonT, port.CellsAt(out, 7), 2, "the day, 2")
	sftRun(port.TextBlob("14.03.2026"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 1, "a day over 12 first: the day, then the month")
	port.AssertEq(emonT, port.CellsAt(out, 6), 3, "month 3")
	port.AssertEq(emonT, port.CellsAt(out, 7), 14, "day 14")
	sftRun(port.TextBlob("03/14/2026"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 6), 3, "a second number over 12 is the day, whatever the order")
	port.AssertEq(emonT, port.CellsAt(out, 7), 14, "so the first is the month")
	sftRun(port.TextBlob("03/04/2026"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 2, "both numbers at most 12 and with no hint: the text as it stands")
	port.AssertEq(emonT, port.CellsAt(out, 4), 10, "its ten characters")
	sftRun(port.TextBlob("03/04/2026"), et, out, 1, 2)
	port.AssertEq(emonT, port.CellsAt(out, 2), 1, "month first by the hint")
	port.AssertEq(emonT, port.CellsAt(out, 6), 3, "month 3")
	port.AssertEq(emonT, port.CellsAt(out, 7), 4, "day 4")
	sftRun(port.TextBlob("03/04/2026"), et, out, 1, 1)
	port.AssertEq(emonT, port.CellsAt(out, 6), 4, "day first by the hint: month 4")
	port.AssertEq(emonT, port.CellsAt(out, 7), 3, "day 3")
	sftRun(port.TextBlob("05/05/2026"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 1, "the same number twice is the same either way")
	sftRun(port.TextBlob("SEALED 12.5.24"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 2, "a two-digit year is a date's shape only: as it stands")
	sftRun(port.TextBlob("NO DIGITS HERE"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 0, "a text with no digits has no date")
	sftRun(port.TextBlob("REG 20261 AND 99"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 0, "numbers that are no date shape are none")
	sftRun(port.TextBlob("2026-13-40"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 0, "a month of 13 is no date")
}

func TestADateOfOtherScriptsAndWordsIsFound(emonT *testing.T) {
	var et *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	sftRun(port.TextBlob("北京市 2026年3月14日 公章"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 1, "the CJK year, month and day marks")
	port.AssertEq(emonT, port.CellsAt(out, 5), 2026, "the year")
	port.AssertEq(emonT, port.CellsAt(out, 6), 3, "the month")
	port.AssertEq(emonT, port.CellsAt(out, 7), 14, "the day")
	port.AssertEq(emonT, port.CellsAt(out, 3), 4, "it starts after the city and a space")
	sftRun(port.TextBlob("서울 2026년 03월 14일"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 0, "Hangul marks with spaces between are not read (no guessing)")
	sftRun(port.TextBlob("٢٠٢٦-٠٣-١٤"), et, out, 2, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 1, "Arabic-Indic digits are digits")
	port.AssertEq(emonT, port.CellsAt(out, 6), 3, "month 3")
	port.AssertEq(emonT, port.CellsAt(out, 7), 14, "day 14")
	sftRun(port.TextBlob("ISSUED 14 March 2026 BY"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 2, "a day, a word and a year: as it stands")
	port.AssertEq(emonT, port.CellsAt(out, 3), 7, "from the day")
	port.AssertEq(emonT, port.CellsAt(out, 4), 13, "to the year's end")
	sftRun(port.TextBlob("ISSUED March 14, 2026 BY"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 2, "a word, a day and a year too")
	port.AssertEq(emonT, port.CellsAt(out, 3), 7, "from the word")
	port.AssertEq(emonT, port.CellsAt(out, 4), 14, "to the year's end")
	sftRun(port.TextBlob("14-Mar-2026"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 2, "hyphens between a day, a word and a year")
	sftRun(port.TextBlob("14 2026"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 2), 0, "a day and a year with no word between is no date")
}

func TestANameIsTheFirstPhraseOfLetters(emonT *testing.T) {
	var et *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	sftRun(port.TextBlob("CITY OF RIVERTON -NOTARY PUBLIC- SEAL"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 0), 0, "the ring's first phrase starts the text")
	port.AssertEq(emonT, port.CellsAt(out, 1), 16, "and is sixteen characters, cut at the hyphen")
	port.AssertEq(emonT, port.CellsAt(out, 8), 1, "its letters are Latin")
	sftRun(port.TextBlob("HARBOR COUNTY CLERK · OFFICIAL SEAL"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 19, "a bullet is a separator")
	sftRun(port.TextBlob("ACME GMBH • HRB 12345 • MUNICH"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 9, "the first phrase, not the register number's")
	sftRun(port.TextBlob("12345 ★ ACME LIMITED"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 0), 8, "a phrase of digits is no name: the next is")
	port.AssertEq(emonT, port.CellsAt(out, 1), 12, "ACME LIMITED")
	sftRun(port.TextBlob("ООО РОМАШКА • ПЕЧАТЬ"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 11, "Cyrillic: two words")
	port.AssertEq(emonT, port.CellsAt(out, 8), 3, "whose letters are Cyrillic")
	sftRun(port.TextBlob("北京某某有限公司★合同专用章"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 0), 0, "Han letters have no spaces: the phrase before the star")
	port.AssertEq(emonT, port.CellsAt(out, 1), 8, "eight letters")
	port.AssertEq(emonT, port.CellsAt(out, 8), 10, "of the Han script")
	sftRun(port.TextBlob("PAID 2026-03-14"), et, out, 2, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 0, "a stamp of one word has no name")
	port.AssertEq(emonT, port.CellsAt(out, 2), 1, "it has a date")
	sftRun(port.TextBlob("APPROVED BY ACCOUNTING 2026-03-14"), et, out, 2, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 22, "a stamp of three words does")
	port.AssertEq(emonT, port.CellsAt(out, 3), 23, "and the date is behind it")
	sftRun(port.TextBlob("SEAL"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 4, "a seal of one word of four letters is named by it")
	sftRun(port.TextBlob("OK"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 0, "two letters are none")
	sftRun(port.TextBlob("Jordan Rivera 2026-03-14"), et, out, 3, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 0, "a signature has no name here")
	port.AssertEq(emonT, port.CellsAt(out, 2), 0, "and no date")
	sftRun(port.TextBlob("CO-OP SOCIETY"), et, out, 1, 0)
	port.AssertEq(emonT, port.CellsAt(out, 1), 13, "a hyphen inside a word is not a separator")
}

func TestTheLocaleHintOrdersANumericDate(emonT *testing.T) {
	var loc *port.Cells = port.NewCells()
	sftPut(port.TextBlob("en-US"), loc)
	port.AssertEq(emonT, sealfield.SfOrder(loc), 2, "US: month first")
	sftPut(port.TextBlob("en_US"), loc)
	port.AssertEq(emonT, sealfield.SfOrder(loc), 2, "with an underscore too")
	sftPut(port.TextBlob("de-DE"), loc)
	port.AssertEq(emonT, sealfield.SfOrder(loc), 1, "Germany: day first")
	sftPut(port.TextBlob("ja"), loc)
	port.AssertEq(emonT, sealfield.SfOrder(loc), 1, "a language alone: day first")
	sftPut(port.TextBlob(""), loc)
	port.AssertEq(emonT, sealfield.SfOrder(loc), 0, "no hint: none")
	port.AssertThat(emonT, sealfield.SfPrep(loc, 0) >= 0, "the answer's scratch is made")
	port.AssertEq(emonT, port.CellsLen(loc), 32, "of 32 cells")
	sealfield.SfPrep(loc, 20)
	port.AssertEq(emonT, port.CellsLen(loc), 52, "and from another cell, after it")
}
